alter table private.payment_intents alter column payment_method_id drop not null;
alter table private.payment_intents add column if not exists payment_flow text not null default 'saved_card';
alter table private.payment_intents add column if not exists provider_session_token text;
alter table private.payment_intents drop constraint if exists payment_intents_payment_flow_check;
alter table private.payment_intents add constraint payment_intents_payment_flow_check check (payment_flow in ('saved_card','checkout_form','pay_with_iyzico','google_pay','apple_pay','carrier_billing','bank_transfer'));
alter table private.payment_intents drop constraint if exists payment_intents_method_flow_check;
alter table private.payment_intents add constraint payment_intents_method_flow_check check ((payment_flow='saved_card' and payment_method_id is not null) or (payment_flow<>'saved_card'));
create unique index if not exists payment_intents_provider_session_token_uidx on private.payment_intents(provider,provider_session_token) where provider_session_token is not null;

create or replace function private.default_payment_control_v1() returns jsonb language sql immutable set search_path='' as $$
select jsonb_build_object('mode','manual_confirmation','provider',null,'checkout_form_enabled',false,'live_card_payments_enabled',false,'card_enrollment_enabled',false,'pay_with_iyzico_enabled',false,'bank_transfer_enabled',false,'google_pay',jsonb_build_object('enabled',false,'environment','TEST','merchant_id',null,'gateway',null,'requires_gateway_approval',true),'apple_pay',jsonb_build_object('enabled',false,'merchant_id',null,'merchant_display_name','Golden Oremar','requires_processor_approval',true),'carrier_billing',jsonb_build_object('enabled',false,'provider',null,'allowed_countries','[]'::jsonb,'requires_commercial_contract',true,'physical_goods_eligibility_confirmed',false),'requires_provider_configuration',true);
$$;
update public.brand_settings set public_config=jsonb_set(public_config,'{payments}',private.default_payment_control_v1() || coalesce(public_config->'payments','{}'::jsonb),true),updated_at=timezone('utc',now()) where slug='golden-oremar';

create or replace function private.prepare_order_hosted_payment_for_service_v1(p_user_id uuid,p_order_id uuid,p_idempotency_key text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare target_order public.orders%rowtype; profile_row public.profiles%rowtype; auth_row auth.users%rowtype; payment_config jsonb; configured_provider text; existing_intent private.payment_intents%rowtype; intent_id uuid; action_value text; items_payload jsonb; basket_price_minor bigint; shipping_discount_minor bigint:=0; split_total_minor bigint:=0;
begin
 if p_user_id is null or p_order_id is null then raise exception 'payment_context_required' using errcode='22023'; end if;
 if p_idempotency_key is null or char_length(p_idempotency_key) not between 16 and 120 or p_idempotency_key !~ '^[A-Za-z0-9_-]+$' then raise exception 'invalid_payment_idempotency_key' using errcode='22023'; end if;
 select private.default_payment_control_v1() || coalesce(bs.public_config->'payments','{}'::jsonb) into payment_config from public.brand_settings bs where bs.slug='golden-oremar' limit 1;
 configured_provider:=nullif(lower(btrim(coalesce(payment_config->>'provider',''))),'');
 if configured_provider<>'iyzico' or not coalesce((payment_config->>'checkout_form_enabled')::boolean,false) then raise exception 'hosted_checkout_not_configured' using errcode='55000'; end if;
 select * into target_order from public.orders where id=p_order_id for update;
 if target_order.id is null or target_order.user_id<>p_user_id then raise exception 'order_not_found' using errcode='P0002'; end if;
 if target_order.payment_status='paid' then return jsonb_build_object('action','terminal','status','captured','orderId',target_order.id,'orderNumber',target_order.order_number,'paymentStatus','paid','orderStatus',target_order.status); end if;
 if target_order.status<>'pending_payment' or target_order.payment_status not in ('unpaid','failed') then raise exception 'order_not_payable' using errcode='55000'; end if;
 if target_order.reservation_expires_at is not null and target_order.reservation_expires_at<=timezone('utc',now()) then raise exception 'payment_reservation_expired' using errcode='55000'; end if;
 if exists(select 1 from private.payment_intents i where i.order_id=target_order.id and i.status in ('processing','authorized') and i.idempotency_key<>p_idempotency_key) then raise exception 'payment_reconciliation_required' using errcode='55000'; end if;
 if exists(select 1 from public.order_items oi left join private.producer_payment_accounts pa on pa.producer_id=oi.producer_id and pa.provider=configured_provider and pa.status='ready' and pa.submerchant_key is not null where oi.order_id=target_order.id and (oi.producer_id is null or pa.producer_id is null)) then raise exception 'producer_payment_account_not_ready' using errcode='55000'; end if;
 select coalesce(sum(oi.line_total_minor),0)::bigint into basket_price_minor from public.order_items oi where oi.order_id=target_order.id;
 select coalesce(op.shipping_discount_minor,0)::bigint into shipping_discount_minor from public.order_promotions op where op.order_id=target_order.id;
 if basket_price_minor<=0 or target_order.total_minor<>basket_price_minor+target_order.shipping_minor-shipping_discount_minor then raise exception 'marketplace_payment_total_mismatch' using errcode='55000'; end if;
 select coalesce(sum(greatest(0,oi.line_total_minor-round((((oi.unit_price_minor*oi.quantity)-oi.discount_minor)::numeric*oi.commission_basis_points_snapshot::numeric)/10000)::bigint)),0)::bigint into split_total_minor from public.order_items oi where oi.order_id=target_order.id;
 if split_total_minor<=0 or split_total_minor>target_order.total_minor then raise exception 'submerchant_payout_exceeds_charge' using errcode='55000'; end if;
 select * into existing_intent from private.payment_intents i where i.user_id=p_user_id and i.idempotency_key=p_idempotency_key for update;
 if existing_intent.id is not null then
   if existing_intent.subject_type<>'order' or existing_intent.subject_id<>target_order.id or existing_intent.order_id<>target_order.id or existing_intent.payment_flow<>'checkout_form' or existing_intent.amount_minor<>target_order.total_minor or existing_intent.currency<>target_order.currency or existing_intent.provider<>configured_provider then raise exception 'payment_idempotency_key_reused' using errcode='23505'; end if;
   intent_id:=existing_intent.id;
   if existing_intent.status='created' then update private.payment_intents set status='processing',attempt_count=attempt_count+1,updated_at=timezone('utc',now()) where id=intent_id; action_value:='initialize';
   elsif existing_intent.status='processing' and existing_intent.provider_session_token is null then action_value:='initialize';
   elsif existing_intent.status in ('processing','authorized') then action_value:='reconcile'; else action_value:='terminal'; end if;
 else
   insert into private.payment_intents(user_id,subject_type,subject_id,order_id,payment_method_id,payment_flow,provider,idempotency_key,amount_minor,currency,status,attempt_count) values(p_user_id,'order',target_order.id,target_order.id,null,'checkout_form',configured_provider,p_idempotency_key,target_order.total_minor,target_order.currency,'processing',1) returning id into intent_id; action_value:='initialize';
 end if;
 select * into profile_row from public.profiles where id=p_user_id; select * into auth_row from auth.users where id=p_user_id;
 if profile_row.id is null or auth_row.id is null or auth_row.email is null then raise exception 'payment_buyer_profile_incomplete' using errcode='55000'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',oi.id,'name',oi.product_name,'quantity',oi.quantity,'lineTotalMinor',oi.line_total_minor,'producerId',oi.producer_id,'subMerchantKey',pa.submerchant_key,'subMerchantPriceMinor',greatest(0,oi.line_total_minor-round((((oi.unit_price_minor*oi.quantity)-oi.discount_minor)::numeric*oi.commission_basis_points_snapshot::numeric)/10000)::bigint)) order by oi.id),'[]'::jsonb) into items_payload from public.order_items oi join private.producer_payment_accounts pa on pa.producer_id=oi.producer_id and pa.provider=configured_provider and pa.status='ready' where oi.order_id=target_order.id;
 return jsonb_build_object('action',action_value,'intentId',intent_id,'intentStatus',coalesce(existing_intent.status,'processing'),'providerSessionToken',existing_intent.provider_session_token,'orderId',target_order.id,'orderNumber',target_order.order_number,'amountMinor',target_order.total_minor,'priceMinor',basket_price_minor,'shippingMinor',target_order.shipping_minor,'shippingDiscountMinor',shipping_discount_minor,'discountMinor',target_order.discount_minor,'currency',target_order.currency,'shippingAddress',target_order.shipping_address,'items',items_payload,'provider',configured_provider,'buyer',jsonb_build_object('id',p_user_id,'displayName',profile_row.display_name,'phone',coalesce(profile_row.phone,target_order.shipping_address->>'phone'),'email',auth_row.email,'createdAt',auth_row.created_at),'splitTotalMinor',split_total_minor);
end;$$;

create or replace function private.store_hosted_payment_session_for_service_v1(p_intent_id uuid,p_token text,p_provider_snapshot jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare intent private.payment_intents%rowtype; normalized_token text:=btrim(coalesce(p_token,'')); snapshot jsonb:=coalesce(p_provider_snapshot,'{}'::jsonb); begin if p_intent_id is null then raise exception 'payment_intent_required' using errcode='22023'; end if; if char_length(normalized_token) not between 8 and 500 or normalized_token ~ '[[:cntrl:]]' then raise exception 'invalid_provider_session_token' using errcode='22023'; end if; if jsonb_typeof(snapshot)<>'object' then raise exception 'invalid_provider_snapshot' using errcode='22023'; end if; select * into intent from private.payment_intents where id=p_intent_id for update; if intent.id is null or intent.payment_flow<>'checkout_form' or intent.status<>'processing' then raise exception 'hosted_payment_intent_invalid' using errcode='55000'; end if; if intent.provider_session_token is not null and intent.provider_session_token<>normalized_token then raise exception 'hosted_payment_session_conflict' using errcode='23505'; end if; update private.payment_intents set provider_session_token=normalized_token,provider_result=provider_result||snapshot,updated_at=timezone('utc',now()) where id=intent.id; return jsonb_build_object('ok',true,'intentId',intent.id,'tokenStored',true,'orderId',intent.order_id); end;$$;
create or replace function private.get_hosted_payment_intent_for_service_v1(p_token text) returns jsonb language plpgsql security definer set search_path='' as $$ declare intent private.payment_intents%rowtype; normalized_token text:=btrim(coalesce(p_token,'')); context jsonb; begin if char_length(normalized_token) not between 8 and 500 then raise exception 'invalid_provider_session_token' using errcode='22023'; end if; select * into intent from private.payment_intents where provider='iyzico' and provider_session_token=normalized_token; if intent.id is null or intent.payment_flow<>'checkout_form' then raise exception 'hosted_payment_session_not_found' using errcode='P0002'; end if; context:=private.get_payment_intent_for_service_v1(intent.id); return context||jsonb_build_object('paymentFlow',intent.payment_flow,'providerSessionToken',intent.provider_session_token); end;$$;

create or replace function private.complete_order_payment_for_service_v2(p_intent_id uuid,p_provider_reference text,p_payment_method_type text,p_status text,p_provider_payload jsonb default '{}'::jsonb,p_failure_code text default null,p_failure_message text default null) returns jsonb language plpgsql security definer set search_path='' as $$
declare intent private.payment_intents%rowtype; normalized_method text:=lower(btrim(coalesce(p_payment_method_type,''))); normalized_status text:=lower(btrim(coalesce(p_status,''))); normalized_reference text:=btrim(coalesce(p_provider_reference,'')); safe_payload jsonb:=coalesce(p_provider_payload,'{}'::jsonb); applied jsonb; split_count integer:=0; payment_id_value uuid; begin if p_intent_id is null then raise exception 'payment_intent_required' using errcode='22023'; end if; if normalized_method not in ('card','bank_transfer','wallet','other') then raise exception 'invalid_payment_method' using errcode='22023'; end if; if normalized_status not in ('authorized','captured','failed','cancelled') then raise exception 'invalid_payment_status' using errcode='22023'; end if; if char_length(normalized_reference) not between 4 and 220 then raise exception 'invalid_payment_reference' using errcode='22023'; end if; if jsonb_typeof(safe_payload)<>'object' then raise exception 'invalid_provider_payload' using errcode='22023'; end if; select * into intent from private.payment_intents where id=p_intent_id for update; if intent.id is null or intent.subject_type<>'order' or intent.order_id is null then raise exception 'payment_intent_not_found' using errcode='P0002'; end if; if intent.status='captured' then return jsonb_build_object('ok',true,'intentId',intent.id,'status','captured','unchanged',true,'orderId',intent.order_id); end if; if intent.status in ('failed','cancelled') and normalized_status=intent.status then return jsonb_build_object('ok',true,'intentId',intent.id,'status',intent.status,'unchanged',true,'orderId',intent.order_id); end if; if intent.status not in ('processing','authorized') then raise exception 'invalid_intent_transition' using errcode='22023'; end if; applied:=private.apply_verified_payment_v1(intent.order_id,intent.provider,normalized_reference,normalized_method,intent.amount_minor,intent.currency,normalized_status,null); payment_id_value:=nullif(applied->>'paymentId','')::uuid; if normalized_status in ('authorized','captured') and payment_id_value is not null then split_count:=private.persist_payment_item_splits_for_service_v1(payment_id_value,safe_payload); end if; update private.payment_intents set status=normalized_status,provider_reference=normalized_reference,failure_code=case when normalized_status='failed' then nullif(btrim(coalesce(p_failure_code,'')),'') else null end,failure_message=case when normalized_status='failed' then nullif(btrim(coalesce(p_failure_message,'')),'') else null end,provider_result=provider_result||safe_payload,completed_at=case when normalized_status in ('captured','failed','cancelled') then timezone('utc',now()) else null end,updated_at=timezone('utc',now()) where id=intent.id; return jsonb_build_object('ok',true,'intentId',intent.id,'status',normalized_status,'orderId',intent.order_id,'payment',applied,'splitCount',split_count); end;$$;

create or replace function public.prepare_order_hosted_payment_for_service_v1(p_user_id uuid,p_order_id uuid,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$ select private.prepare_order_hosted_payment_for_service_v1(p_user_id,p_order_id,p_idempotency_key); $$;
create or replace function public.store_hosted_payment_session_for_service_v1(p_intent_id uuid,p_token text,p_provider_snapshot jsonb default '{}'::jsonb) returns jsonb language sql security definer set search_path='' as $$ select private.store_hosted_payment_session_for_service_v1(p_intent_id,p_token,p_provider_snapshot); $$;
create or replace function public.get_hosted_payment_intent_for_service_v1(p_token text) returns jsonb language sql security definer set search_path='' as $$ select private.get_hosted_payment_intent_for_service_v1(p_token); $$;
create or replace function public.complete_order_payment_for_service_v2(p_intent_id uuid,p_provider_reference text,p_payment_method_type text,p_status text,p_provider_payload jsonb default '{}'::jsonb,p_failure_code text default null,p_failure_message text default null) returns jsonb language sql security definer set search_path='' as $$ select private.complete_order_payment_for_service_v2(p_intent_id,p_provider_reference,p_payment_method_type,p_status,p_provider_payload,p_failure_code,p_failure_message); $$;
revoke all on function public.prepare_order_hosted_payment_for_service_v1(uuid,uuid,text) from public,anon,authenticated; revoke all on function public.store_hosted_payment_session_for_service_v1(uuid,text,jsonb) from public,anon,authenticated; revoke all on function public.get_hosted_payment_intent_for_service_v1(text) from public,anon,authenticated; revoke all on function public.complete_order_payment_for_service_v2(uuid,text,text,text,jsonb,text,text) from public,anon,authenticated; grant execute on function public.prepare_order_hosted_payment_for_service_v1(uuid,uuid,text) to service_role; grant execute on function public.store_hosted_payment_session_for_service_v1(uuid,text,jsonb) to service_role; grant execute on function public.get_hosted_payment_intent_for_service_v1(text) to service_role; grant execute on function public.complete_order_payment_for_service_v2(uuid,text,text,text,jsonb,text,text) to service_role;

create or replace function public.get_checkout_payment_capabilities_v2() returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('hostedCheckout',coalesce((cfg->>'checkout_form_enabled')::boolean,false),'card',coalesce((cfg->>'live_card_payments_enabled')::boolean,false),'savedCard',coalesce((cfg->>'card_enrollment_enabled')::boolean,false),'payWithIyzico',coalesce((cfg->>'pay_with_iyzico_enabled')::boolean,false),'bankTransfer',coalesce((cfg->>'bank_transfer_enabled')::boolean,false),'googlePay',coalesce((cfg->'google_pay'->>'enabled')::boolean,false),'applePay',coalesce((cfg->'apple_pay'->>'enabled')::boolean,false),'carrierBilling',coalesce((cfg->'carrier_billing'->>'enabled')::boolean,false),'carrierBillingProvider',case when coalesce((cfg->'carrier_billing'->>'enabled')::boolean,false) then cfg->'carrier_billing'->>'provider' else null end) from (select private.default_payment_control_v1() || coalesce(bs.public_config->'payments','{}'::jsonb) cfg from public.brand_settings bs where bs.slug='golden-oremar') s; $$;
revoke all on function public.get_checkout_payment_capabilities_v2() from public; grant execute on function public.get_checkout_payment_capabilities_v2() to anon,authenticated;
